Deno.test('buildQuizPrompt: enforces option length consistency for mc questions', () => {
  const docs = [{ id: '1', filename: 'a.pdf', extracted_text: 'x' }];
  const prompt = buildQuizPrompt(docs, 10);
  assertContains(prompt, '字符长度差异必须 ≤ 10%');
